for cid, title, size, deps, goal, acc, src, note in API:
    card(id=cid, phase=6, title=title, owner="core agent", size=size, deps=deps, goal=goal,
         files=[("contract PR", "`docs/themes/contract.md`", "additive change, modelVersion/apiVersion stay 1")],
         steps=["Contract amendment first (a `contract` PR), then the implementation."],
         tests=["host tests + the consuming renderer's contract run"], accept=[acc], short=acc, src=src, notes=[note])

