for cid, slug, name, cm, cm2, concept, deps, needs in PROPOSALS:
    branch = f"evidence/issue-330-theme-{slug}"
    src = [cm] + ([cm2] if cm2 else [])
    card(id=cid, phase=6, title=f"Port the {name} proposal as a renderer", owner="renderer agent", size="M", deps=deps, repo="hachidori-theme-store",
         goal=concept + " Port it from the onRender prototype to its own popup on the v1 contract (c26/c28): build from the model, never scrape or hide Default.",
         files=[("new", f"`themes/{slug}/{{theme.yaml,renderer.js,renderer.css,README.md,screenshot.png}}`", "from the proposal's files"),
                ("evidence", EV(branch, f"docs/evidence/issue-330/themes/{slug}", branch), "screenshots, capture script, evidence.json, benchmark")],
         steps=[f"Needs: {needs}.", "Re-verify the proposal's accessibility table (contrast, forced-colors, reduced motion, keyboard) on the port."],
         tests=["themes CI gates (validate, lint, contract, render, benchmark)"],
         accept=["Gates green including the end-to-end budget; screenshots comparable to the proposal; bee-san approves inclusion."],
         short="Renderer port; all gates green; bee-san approves", src=src)
